"""Post hoc (r6/POSTHOC_R6.md). LaTeX macros and the compact round-6 table from r6/results/R6_posthoc.json and R6_summary.json
(no private inputs). Writes paper_workshop/tables/numbers_r6p.tex and tab_r6_compact.tex.
Usage: python r6/make_tables_r6_posthoc.py  (after r6/posthoc_r6.py and r6/make_tables_r6.py)."""
import os, sys, json, math
R = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
sys.path.insert(0, os.path.join(R, 'r4'))
from make_tables_r4 import f, mm, NAME  # noqa: E402
OUT = os.path.join(R, 'paper_workshop', 'tables')
P = json.load(open(os.path.join(R, 'r6', 'results', 'R6_posthoc.json'))); SC = json.load(open(os.path.join(R, 'r6', 'results', 'R6_summary.json')))['scores']
NW = ('zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen')
VS = {'ENERGY-DRIVEN': 'energy-driven', 'NOT ENERGY-DRIVEN': 'not energy-driven', 'MIXED': 'mixed'}
mac = {}
def M(k, v): mac[k] = v
def g(v, d=2): return '--' if v is None or (isinstance(v, float) and not math.isfinite(v)) else f(v, d)
def gm(v, d=2): x = g(v, d); return x if x == '--' else mm(x)
def write(name, body): open(os.path.join(OUT, name), 'w').write('% generated by r6/make_tables_r6_posthoc.py -- do not edit\n' + body)

C = P['controls']; MG = P['magnitude']; VF = P['vim_frozen']; VI = P['vinfo']
ROWS = [  # (label, tau_EQ dict, R_B median, magnitude key, verdict, group)
    ('NuSA share', SC['NuSA']['tau_EQ'], SC['NuSA']['R_B_median'], 'NuSA', SC['NuSA']['energy_verdict'], 'c'),
    ('$\\rho$ itself', C['rho']['tau_EQ'], C['rho']['R_B_median'], None, C['rho']['energy_verdict'], 'c'),
    ('SING AS, released', C['AS_released']['tau_EQ'], C['AS_released']['R_B_median'], 'AS_released', C['AS_released']['energy_verdict'], 'c'),
    ('SING AS, retrained', C['AS_retrained']['tau_EQ'], C['AS_retrained']['R_B_median'], 'AS_retrained', C['AS_retrained']['energy_verdict'], 'c'),
    ('SING IS, released', C['IS_released']['tau_EQ'], C['IS_released']['R_B_median'], 'IS_released', C['IS_released']['energy_verdict'], 'c'),
    ('SING IS, retrained', C['IS_retrained']['tau_EQ'], C['IS_retrained']['R_B_median'], 'IS_retrained', C['IS_retrained']['energy_verdict'], 'c'),
    ('ViM', SC['ViM']['tau_EQ'], SC['ViM']['R_B_median'], 'ViM', SC['ViM']['energy_verdict'], 's'),
    ('ViM, $\\alpha$ frozen$^{\\dagger}$', VF['tau_EQ'], VF['R_B_median'], 'ViM_frozen', VF['energy_verdict'], 's'),
    ('ActSub $S_{\\to}$', SC['ActSub']['tau_EQ'], SC['ActSub']['R_B_median'], 'ActSub', SC['ActSub']['energy_verdict'], 's'),
    ('CORE $S_{\\mathrm{mem}}$', SC['CORE']['tau_EQ'], SC['CORE']['R_B_median'], 'CORE', SC['CORE']['energy_verdict'], 's'),
    ('$\\mathcal{V}$-information', SC['Vinfo']['tau_EQ'], SC['Vinfo']['R_B_median'], 'Vinfo', SC['Vinfo']['energy_verdict'], 's')]
body = ('\\begin{tabular}{@{}lccccl@{}}\n\\toprule\n & \\multicolumn{2}{c}{$\\tau_{\\mathrm{EQ}}$} & & range left & rule \\\\\n'
        'Score & E12 & S11 & med.\\ $R_B$ & after E1 & output \\\\\n\\midrule\n\\multicolumn{6}{@{}l}{\\emph{Positive controls (energy scores or SING\'s own score; post hoc except NuSA)}} \\\\\n')
for i, (lab, t, rb, mk, v, grp) in enumerate(ROWS):
    if grp == 's' and ROWS[i - 1][5] == 'c': body += '\\midrule\n\\multicolumn{6}{@{}l}{\\emph{Audited scores (pre-registered; frozen-$\\alpha$ ViM post hoc)}} \\\\\n'
    body += f'{lab} & {gm(t["E12"])} & {gm(t["S11"])} & {gm(rb)} & {gm(MG[mk]["E12"]) if mk else "$0$"} & {VS[v]} \\\\\n'
write('tab_r6_compact.tex', body + '\\bottomrule\n\\end{tabular}\n')

for k, nm in (('AS_released', 'ASrel'), ('AS_retrained', 'ASret'), ('IS_released', 'ISrel'), ('IS_retrained', 'ISret')):
    c = C[k]; M(f'RP{nm}EqE', g(c['tau_EQ']['E12'])); M(f'RP{nm}EqS', g(c['tau_EQ']['S11'])); M(f'RP{nm}RB', g(c['R_B_median'])); M(f'RP{nm}RBE', g(c['R_B_median_E12']))
    M(f'RP{nm}Verdict', VS[c['energy_verdict']]); M(f'RP{nm}Mag', g(MG[k]['E12'])); M(f'RP{nm}NE', str(c['n_E12'])); M(f'RP{nm}NS', str(c['n_S11']))
M('RPVimFrEqE', g(VF['tau_EQ']['E12'])); M('RPVimFrEqS', g(VF['tau_EQ']['S11'])); M('RPVimFrRB', g(VF['R_B_median'])); M('RPVimFrVerdict', VS[VF['energy_verdict']])
M('RPVimFrMag', g(MG['ViM_frozen']['E12'])); M('RPVimMag', g(MG['ViM']['E12']))
for n, nm in (('resnet', 'Res'), ('dinov2', 'Dino'), ('vgg16', 'Vgg')):
    M(f'RPVim{nm}Real', g(VF['real'][n], 3)); M(f'RPVim{nm}Frozen', g(VF['E1_frozen'][n], 2 if VF['E1_frozen'][n] >= 0.01 else 3)); M(f'RPVim{nm}Alpha', g(VF['alpha_ratio_E1'][n], 1))
ar = list(VF['alpha_ratio_E1'].values()); M('RPVimAlphaMin', g(min(ar), 1)); M('RPVimAlphaMax', g(max(ar), 1))
fr = list(VF['E1_frozen'].values()); M('RPVimFrozenMax', g(max(fr), 4))
for k, nm in (('NuSA', 'Nusa'), ('ActSub', 'Act'), ('CORE', 'Core'), ('Vinfo', 'Vinfo'), ('CORE_ker', 'CoreKer'), ('ViM_s', 'VimS')):
    M(f'RP{nm}Mag', g(MG[k]['E12']))
M('RPTauNullTwelve', g(P['tau_null']['12']['p_lt_03'])); M('RPTauNullEleven', g(P['tau_null']['11']['p_lt_03']))
M('RPVinfoRangeAll', g(VI['range13'], 4)); M('RPVinfoRangeNoD', g(VI['range_without_densenet'], 4)); M('RPVinfoDShare', f'{100 * VI["densenet_share_of_range"]:.0f}\\%')
M('RPVinfoNoDEstE', str(VI['n_E12_without_densenet'])); M('RPVinfoNoDEstS', str(VI['n_S11_without_densenet']))
M('RPVinfoNoDVerdictPossible', 'yes' if VI['verdict_possible_without_densenet'] else 'no'); M('RPVinfoNoDRB', g(VI['R_B_median_without_densenet_all12']))
NP = [n for n in VI['real'] if n in VI['nonpositive'] or n in VI['below_1e4']]   # negative, or zero to four decimals
M('RPVinfoNonpos', str(len(NP))); M('RPVinfoNonposw', NW[len(NP)]); M('RPVinfoTwoSD', str(len(VI['within_2sd_of_zero'])))
M('RPVinfoTauNoDE', g(VI['tau_EQ_without_densenet_est']['E12'])); M('RPVinfoTauNoDS', g(VI['tau_EQ_without_densenet_est']['S11']))
M('RPVinfoNonposList', ', '.join(f'{NAME[n]} ${f(VI["real"][n], 4)}$' for n in NP))
M('RPVinfoCtwoGtCone', str(len(VI['C2_gt_C1']))); M('RPVinfoLamTop', str(VI['lam_top'])); M('RPVinfoLamN', str(VI['lam_n']))
M('RPCtwoSynReal', g(P['c2_synthetic']['gain_real'])); M('RPCtwoSynPerm', g(P['c2_synthetic']['gain_within_class_perm']))
rp = VI.get('repro_resnet')
if rp:
    ch = [f'{c["A"]:g}/{c["B"]:g}' for c in rp['chosen']]; M('RPReproChosen', ', '.join(sorted(set(ch)))); M('RPReproReps', str(len(ch)))
    for k, v in rp['real_by_lam'].items():
        M('RPReproReal' + k.replace('|', 'x').replace('0.1', 'S').replace('1.0', 'L'), g(v, 5))
# round-5 SO_null with exact hollow double-centring (post hoc, r5/so_exact_r5.py)
sp = os.path.join(R, 'r5', 'results', 'posthoc', 'SO_exact_summary.json')
if os.path.exists(sp):
    SO = json.load(open(sp)); M('RPSOMaxDiff', g(SO['max_abs_diff'], 4)); M('RPSOTauOldNew', g(SO['tau_r5_vs_x_all13'])); M('RPSORepro', f'{SO["r5_reproduced_max_diff"]:.0e}'.replace('e-', r'{\times}10^{-').replace('{-0', '{-') + '}')
    M('RPSOGTwo', str(SO['G2_pass'])); M('RPSOGThree', str(SO['G3_pass'])); M('RPSONEst', str(SO['n_est_x'])); M('RPSOLabel', SO['SO_x']['label'])
    for s_, k_ in (('all13', 'All'), ('E12', 'E'), ('S11', 'S')):
        M('RPSOTau' + k_, g(SO['SO_x'][s_]['tau']['tau'])); M('RPSOTauOld' + k_, g(SO['SO_r5'][s_]['tau']['tau']))
open(os.path.join(OUT, 'numbers_r6p.tex'), 'w').write('% generated by r6/make_tables_r6_posthoc.py -- do not edit\n' + ''.join(f'\\newcommand{{\\{k}}}{{{v}}}\n' for k, v in sorted(mac.items())))
print('wrote', len(mac), 'macros')
